class Node:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None


def insert(node, value):
    if node is None:
        return Node(value)
    if value < node.value:
        node.left = insert(node.left, value)
    elif value > node.value:
        node.right = insert(node.right, value)
    return node


def build(values):
    root = None
    for v in values:
        root = insert(root, v)
    return root


def search_path(values, target):
    node = build(values)
    path = []
    while node is not None:
        path.append(node.value)
        if target == node.value:
            break
        node = node.left if target < node.value else node.right
    return path

